<?php
namespace App\Http\Controllers; use App\Models\Documento; use App\Models\TipoDocumento; use Illuminate\Http\Request;
class DocumentoController extends Controller { public function index(){return view('documentos.index');} public function data(Request $r){$q=Documento::with(['tipo','tercero','bodega','usuario','comprobantesContables'])->latest('id');foreach(['tipo_documento_id','tercero_id','bodega_id','estado'] as $campo)if($r->filled($campo))$q->where($campo,$r->input($campo));if($r->filled('desde'))$q->whereDate('fecha','>=',$r->input('desde'));if($r->filled('hasta'))$q->whereDate('fecha','<=',$r->input('hasta'));if($r->filled('buscar'))$q->where(fn($x)=>$x->where('numero','like','%'.$r->input('buscar').'%')->orWhere('prefijo','like','%'.$r->input('buscar').'%'));return response()->json(['data'=>$q->paginate(30),'tipos'=>TipoDocumento::where('activo',true)->get(['id','codigo','nombre'])]);} public function show(Documento $documento){return response()->json($documento->load(['tipo','tercero','bodega','usuario','detalles.producto','movimientosInventario','comprobantesContables.movimientos']));} }
